<template><section class="submission"><h2>提交作业</h2><textarea v-model="form.content" placeholder="填写作业内容"></textarea><div class="upload"><input ref="picker" type="file" multiple accept=".zip,.pdf,.doc,.docx,.ppt,.pptx" @change="selectFiles"/><button type="button" @click="picker?.click()">选择附件</button><span>支持 ZIP、PDF、Word、PPT，单个文件不超过 20MB</span></div><ul v-if="files.length"><li v-for="file in files" :key="file.name + file.size"><span>{{ file.name }}（{{ formatSize(file.size) }}）</span><button type="button" @click="removeFile(file)">删除</button></li></ul><textarea v-model="form.note" placeholder="备注（可选）"></textarea><button class="primary" :disabled="saving" @click="submit">{{ saving ? '提交中…' : '提交作业' }}</button></section></template>
<script setup>
import { ref } from 'vue';import { ElMessage } from 'element-plus';import { submitAssignment,uploadStudentFile } from '@/api/student';import { getErrorMessage } from '@/api/response'
const props=defineProps({assignmentId:[String,Number],initialContent:String,initialNote:String});const emit=defineEmits(['submitted']);const picker=ref();const files=ref([]);const saving=ref(false);const form=ref({content:props.initialContent||'',note:props.initialNote||''});const allowed=['zip','pdf','doc','docx','ppt','pptx'];const formatSize=v=>v<1024*1024?Math.ceil(v/1024)+'KB':(v/1024/1024).toFixed(1)+'MB';const selectFiles=e=>{for(const file of e.target.files){const ext=file.name.split('.').pop().toLowerCase();if(!allowed.includes(ext)){ElMessage.error('不支持文件：'+file.name);continue}if(file.size>20*1024*1024){ElMessage.error('文件超过20MB：'+file.name);continue}if(!files.value.some(item=>item.name===file.name&&item.size===file.size))files.value.push(file)}e.target.value=''};const removeFile=file=>{files.value=files.value.filter(item=>item!==file)};const submit=async()=>{saving.value=true;try{const attachments=[];for(const file of files.value){const stored=await uploadStudentFile(file);attachments.push(stored.key)}await submitAssignment(props.assignmentId,{content:form.value.content,note:form.value.note,attachments});ElMessage.success('作业已提交');emit('submitted')}catch(e){ElMessage.error(getErrorMessage(e,'提交失败'))}finally{saving.value=false}}
</script>
<style scoped>.submission{padding-top:20px}.submission h2{color:#334155;font-size:17px}.submission textarea{box-sizing:border-box;width:100%;min-height:100px;margin-bottom:12px;padding:12px;border:1px solid #dbe3ea;border-radius:6px;resize:vertical;font:inherit}.upload{display:flex;align-items:center;gap:12px;margin-bottom:12px}.upload input{display:none}.upload button,.primary{padding:10px 18px;border:0;border-radius:6px;color:#fff;background:#356798;cursor:pointer}.upload span{color:#8795a6;font-size:12px}.submission ul{margin:0 0 12px;padding:0;list-style:none}.submission li{display:flex;justify-content:space-between;padding:9px 12px;border-bottom:1px solid #edf1f4;color:#52657a;font-size:13px}.submission li button{border:0;color:#b42318;background:none;cursor:pointer}.primary:disabled{opacity:.5}</style>
